_N2_DNP_OBR = 0.009          # obroncy-starterzy bez statusu + Full (n=1021)
_N2_SIGMA_TACKLE = 0.15      # brak rynku -> szerokie sigma parametru


def _n2_pmf_biny(pmf, kraw):
    """Rozklad calkowity (indeks = wartosc) -> prawdopodobienstwa binow."""
    out, lo = [], -1
    for k in kraw:
        out.append(float(sum(pmf[lo + 1:k + 1])))
        lo = k
    out.append(float(sum(pmf[kraw[-1] + 1:])))
    return out


def _n2_nb(mean, vm, kmax):
    """Rozklad ujemny dwumianowy o sredniej mean i wariancji/sredniej vm; vm <= 1 -> Poisson (jak rynki.nb_pmf)."""
    if mean <= 0:
        raise ValueError("srednia <= 0")
    if vm <= 1 + 1e-9:
        lm = math.log(mean)
        pmf = [math.exp(-mean + k * lm - math.lgamma(k + 1)) for k in range(kmax + 1)]
    else:
        p = 1.0 / vm
        r = mean / (vm - 1.0)
        pmf = [math.exp(math.lgamma(k + r) - math.lgamma(r) - math.lgamma(k + 1) + r * math.log(p) + k * math.log1p(-p))
               for k in range(kmax + 1)]
    s = sum(pmf)
    return np.array([x / s for x in pmf])


def _n2_mieszaj(mean, vm, kmax, sigma):
    pm = np.zeros(kmax + 1)
    for mult, w in ((1 - sigma, 0.25), (1.0, 0.5), (1 + sigma, 0.25)):
        pm += w * _n2_nb(mean * mult, vm, kmax)
    return pm


def _n2_dopasuj_nb(pts, vm, kmax, lo=0.2, hi=40.0):
    """Srednia NB tak, by ogony P(X >= t) pasowaly do rynku (najmniejsze kwadraty; jak rynki.fit_nb_mean)."""
    def blad(m):
        pmf = _n2_nb(m, vm, kmax)
        return sum((float(pmf[t:].sum()) - p) ** 2 for t, p in pts)
    for _ in range(200):
        a, b = lo + (hi - lo) / 3, hi - (hi - lo) / 3
        if blad(a) < blad(b):
            hi = b
        else:
            lo = a
    return (lo + hi) / 2


def _n2_polowkowe(linie):
    lad = [(l, p, n) for l, p, n in linie if float(l) != int(float(l))]
    assert lad, "brak linii x.5 w drabince - podaj linie z polowkami"
    return lad


def _n2_mediana(lad, skala):
    return sum((l + (p - 0.5) * skala) * n for l, p, n in lad) / sum(n for _, _, n in lad)


def _n2_przechyl(hist, cel):
    """Przechylenie wykladnicze rozkladu calkowitego do zadanej sredniej."""
    ks = np.arange(len(hist))
    lo, hi = -1.0, 1.0
    for _ in range(200):
        th = (lo + hi) / 2
        w = hist * np.exp(th * ks)
        w = w / w.sum()
        if float((w * ks).sum()) < cel:
            lo = th
        else:
            hi = th
    w = hist * np.exp(((lo + hi) / 2) * ks)
    return w / w.sum()


def _n2_dnp(p, kraw, status):
    """status = klucz DANE["dnp"] (np. "brak_full", "q_limited") albo liczba (p niegrania). None = bez DNP."""
    if status is None:
        return list(p)
    d = float(status) if not isinstance(status, str) else DANE["dnp"][status]
    z = np.array(_biny([0.0], kraw))
    return list((1 - d) * np.asarray(p) + d * z)


def _n2_ok(p):
    assert abs(sum(p) - 1) < 1e-6 and min(p) >= 0, ("suma/nieujemnosc", sum(p), min(p))
    return [float(x) for x in p]


def nfl_zwyciezca(kursy, remis=True, p_remis=None):
    """Zwyciezca meczu. kursy = lista per ksiazka: (kurs_amerykanski_A, kurs_amerykanski_B) albo od razu p_A (liczba 0-1, po devigu);
    A = druzyna wymieniona PIERWSZA w quizie (kolejnosc binow jak w quizie - sprawdz!). Mediana p_A po ksiazkach.
    remis=True (quiz ma opcje Tie/remis): [(1-pt)*pA, (1-pt)*pB, pt], pt = 0,345 % (10/2895 meczow REG 2015-25, p_remis);
    remis=False (tylko 2 druzyny): [pA, pB]. Zwraca [pA, pB(, pt)]."""
    ps = sorted(devig(*k) if isinstance(k, (tuple, list)) else float(k) for k in kursy)
    n = len(ps)
    pa = ps[n // 2] if n % 2 else (ps[n // 2 - 1] + ps[n // 2]) / 2
    if not remis:
        return _n2_ok([pa, 1 - pa])
    pt = DANE_NFL2["p_remis"] if p_remis is None else p_remis
    return _n2_ok([(1 - pt) * pa, (1 - pt) * (1 - pa), pt])


def nfl_jardy_podan(linie, kraw, status=None):
    """Jardy podania QB (rynek 103). Mediana z drabinki (linia + (p_over-0,5)*200, wazona liczba ksiazek), ksztalt wzgledny QB (n=4920 gier)
    skalowany SREDNIA = mediana / mediana_ksztaltu, zaokraglenie do calych jardow, plus 3,7 % wczesnego zejscia (QB < 15 podan, jardy ~40-160).
    status: None = bez DNP (tak liczyl komputer, gdy QB bez statusu); klucz DANE["dnp"] albo liczba, gdy QB ma status/jest niepewny."""
    med = _n2_mediana(_n2_polowkowe(linie), 200.0)
    q = np.array(DANE_NFL2["qb_yds"]["q"])
    p = np.array(_biny(np.round(med / DANE_NFL2["qb_yds"]["med"] * q), kraw))
    p = (1 - P_KRZYWO) * p + P_KRZYWO * np.array(_biny([40.0, 70.0, 100.0, 130.0, 160.0], kraw))
    return _n2_ok(_n2_dnp(p, kraw, status))


def nfl_proby_biegowe(linie, kraw, status="brak_full"):
    """Proby biegowe RB (rynek 106). NB (vm 2,025) dopasowana do drabinki daje srednia; ksztalt EMPIRYCZNY klasy RB o sredniej 14-22 prob
    (n=2636 gier, lapie wczesne zejscie) skalowany srednia / mediana_ksztaltu, zaokraglony; domieszka DNP (status jak w szablonie, domyslnie 0,8 %).
    Starsze quizy (do 28.09) liczone bez DNP: status=None."""
    lad = _n2_polowkowe(linie)
    r = DANE_NFL2["rb_att"]
    mean = _n2_dopasuj_nb([(int(math.ceil(l)), p) for l, p, n in lad], r["vm"], 60)
    p = _biny(np.round(mean / r["med"] * np.array(r["q"])), kraw)
    return _n2_ok(_n2_dnp(p, kraw, status))


def nfl_td_mecz(total, kraw, pas=3.0):
    """Liczba przylozen w meczu (WSZYSTKIE TD obu druzyn). BRAK RYNKU. Empiria meczow 2015-25 z linia w [total-3, total+3] (2895 meczow, +0,01 na
    kazda liczbe TD 0-19), przechylona wykladniczo do sredniej z regresji td = a + b*total (cala proba). total = linia totalu punktow meczu (np. 46.5)."""
    hist = np.full(20, 0.01)
    for ln, c in DANE_NFL2["td_linie"].items():
        if total - pas - 1e-9 <= float(ln) <= total + pas + 1e-9:
            hist += np.array(c, dtype=float)
    b = DANE_NFL2["td_beta"]
    w = _n2_przechyl(hist / hist.sum(), b[0] + b[1] * total)
    return _n2_ok(_n2_pmf_biny(list(w), kraw))


def nfl_kwarta(total, ot=True, pas=3.0):
    """Najwyzej punktujaca kwarta. BRAK RYNKU. Empiria meczow 2015-25 z linia w [total-3, total+3]: ktora kwarta ma STRICTE najwiecej punktow, remis kwart = Tie.
    ot=True (quiz ma przycisk Overtime): [1st,2nd,3rd,4th,Overtime,Tie], dogrywka liczona jako 5. okres (jeden przycisk nie zalezy od kwart);
    ot=False (tylko 1st-4th + Tie): [1st,2nd,3rd,4th,Tie], dogrywka pominieta. Kolejnosc binow sprawdz w quizie (Tie bywa ostatni)."""
    suma = None
    for ln, c in DANE_NFL2["kw_linie"].items():
        if total - pas - 1e-9 <= float(ln) <= total + pas + 1e-9:
            c = np.array(c[5:] if ot else c[:5], dtype=float)
            suma = c if suma is None else suma + c
    assert suma is not None and suma.sum() > 100, "za malo meczow w pasie linii"
    return _n2_ok(list(suma / suma.sum()))


def _n2_lam(g):
    """Srednia solo/mecz z regresji (przed korekta tempa meczu). g = slownik gracza, patrz nfl_solo."""
    if "pred" in g:
        return float(g["pred"])
    solo = [float(x) for x in g["solo"]]
    sr = sum(solo) / len(solo)
    K = int(g.get("K", len(solo)))
    kl = g["klasa"]
    na_snap = g.get("na_snap25")
    reg = DANE_NFL2["tackle"]["reg"]["prior" if na_snap is not None else "bez"][kl]
    ks = sorted(int(k) for k in reg)
    K = min(max(K, ks[0]), ks[-1])
    b = g.get("beta") or reg[str(K)]["beta"]
    if na_snap is None:
        return float(b[0] + b[1] * sr)
    udz = float(g["udzial"]) if "udzial" in g else sum(g["snap"]) / len(g["snap"])
    return float(b[0] + b[1] * na_snap * udz + b[2] * sr)


def nfl_solo(gracze, total, kraw):
    """Solo tackle JEDNEGO gracza albo LACZNIE kilku (Q: 'X & Y make combined'). BRAK RYNKU - regresja z nflverse (patrz naglowek pliku).
    gracze = lista slownikow (1 albo 2 gracze):
      "klasa": "LB" | "CB" | "S"   (S = safety: S, SS, FS, SAF; CB = CB/DB; LB = LB, ILB, MLB, OLB; DL/EDGE NIE zmierzone - nie liczyc tym narzedziem)
      "solo":  [solo tackle w kazdym meczu TEGO sezonu, mecze z defense_pct >= 0.30, po kolei]
      "snap":  [defense_pct w tych samych meczach]
      "na_snap25": solo na PELNY snap w poprzednim sezonie = suma solo / suma defense_pct (mecze >= 0.30), wymaga >= 8 meczow; None / brak = debiutant
      opcjonalnie: "udzial" (nadpisuje srednia snap, np. gdy kolega z formacji wypadl), "K" (liczba pierwszych meczow do regresji, domyslnie len(solo)),
      "pred" (gotowa srednia - pomija regresje), "beta" (gotowe wspolczynniki), "dnp" (domyslnie 0,9 %),
      "status": "Questionable_Limited" | "Questionable_wszystkie" (gracz Q: udzial snapow losowany z zmierzonego rozkladu, zamiast DNP; "norm" = udzial gdy gra, domyslnie 1.0).
    Srednia gracza = regresja (z priorem 2025: a + b1*na_snap25*udzial + b2*sr_sezonu; debiutant: a + b*sr_sezonu) x tempo meczu
    (1 + 0,004408*(total - 45,218)); rozklad: NB vm 0,983 (czyli Poisson) rozmyty sigma 0,15; sumy = splot niezaleznych (korelacja -0,07 pominieta)."""
    T = DANE_NFL2["tackle"]
    tempo = 1 + T["tempo_nach"] * (total - T["tempo_sr_linia"])
    suma = np.ones(1)
    for g in gracze:
        lam = _n2_lam(g) * tempo
        sig = g.get("sigma", _N2_SIGMA_TACKLE)
        if g.get("status"):
            norm = g.get("norm", 1.0)
            x = np.zeros(31)
            for pct in DANE_NFL2["kont"][g["status"]]:
                u = min(pct / norm, 1.0)
                if u <= 0:
                    x[0] += 1.0
                else:
                    x += _n2_mieszaj(lam * u, T["vm"], 30, sig)
            x /= x.sum()
        else:
            d = g.get("dnp", _N2_DNP_OBR)
            x = _n2_mieszaj(lam, T["vm"], 30, sig) * (1 - d)
            x[0] += d
        suma = np.convolve(suma, x)
    return _n2_ok(_n2_pmf_biny(list(suma / suma.sum()), kraw))


