# MODUL MLB
# ====================================================================================================
"""MLB - marginalia WSZYSTKICH typow pytan z quizow 9-14, metoda DOKLADNIE jak na komputerze (quiz14-calc.py + rynki.py).

TYP PYTANIA                                  -> WYWOLANIE (kraw = mlb_kraw(["0-2","3","4","5","6","7+"]) = [2,3,4,5,6])
 ile runow zdobedzie druzyna X (team total)  -> mlb_runy_druzyny(linie, kraw)           linie = [(4.5, p_over, n_ksiazek), ...]
 ile runow w meczu (total)                   -> mlb_runy_total(linie, kraw)
 ile home runow w meczu                      -> mlb_hr_mecz(propsy_hr, kraw, total_meczu=None)     propsy = z mlb_anytime(...)
 ile doubli w meczu                          -> mlb_double_mecz(propsy_2b, kraw, total_meczu=None)
 czy X albo Y uderzy HR (Yes/No)             -> mlb_hr_binarne([(p_hr, w_skladzie, hr_na_pa), (...)], potwierdzone=False)  -> [P(Yes), P(No)]
 ile hitow lacznie dwaj gracze               -> mlb_hity_dwoch([(linie_hitow, slot), (linie_hitow, slot)], kraw, potwierdzone=False)
 ile strikeoutow w meczu                     -> mlb_strikeouty([starter_a, starter_b], kraw)       starter = {"k": linie|lambda, "outy": linie|"ip": IP, "idx": K% ataku rywala / liga}
 ile walkow (BB) w meczu                     -> mlb_walki([starter_a, starter_b], kraw)            starter = {"bb": linie|lambda, "outy"|"ip", "idx": BB% ataku rywala / liga}
 K / BB / HR / 2B BEZ propsow na rynku       -> mlb_bez_rynku("k"|"bb"|"hr"|"2b", [(atak, pitching, starter|None), (...)], kraw, park=1.0)
Pomocnicze: mlb_linie(wiersze) (kursy kilku ksiazek -> mediana p per linia), mlb_anytime(gracze) (kursy anytime -> p),
 mlb_srednia_runow(linie), mlb_kontrola_totalu(total, tt_a, tt_b), mlb_idx("CWS", "k") (tabela druzyn), mlb_stan(), mlb_biny(srednia, vm, kraw).
Wszystkie funkcje zwracaja LISTE prawdopodobienstw w kolejnosci binow (suma 1); drukuja ostrzezenia "[mlb] [!]" (MLB_CICHO = True wycisza).

GDZIE W INTERNECIE BRAC WEJSCIA (komputer mial BettingPros; w chmurze: wyszukiwarka, strony ksiazek, covers/actionnetwork/oddsshark):
 - total meczu, team total: linie O/U + kursy Over/Under (kilka ksiazek) -> mlb_linie -> p_over; tylko linie POLOWKOWE (8.5), calkowite maja push.
 - props anytime HR / 2B (WSZYSTKIE nazwiska z tablicy meczu; komputer bral 18 najwyzszych) -> mlb_anytime. HR i 2B licz na tablicy jak najpozniej
   (rano w dniu meczu tablica jest niepelna: mnozniki byly mierzone na kursach ZAMKNIECIA - ostrzezenie "tablica niedojrzala").
 - hity gracza: linie 0.5 i 1.5 (obie!), slot w lineupie (rotowire/mlb.com), skladu projected vs confirmed.
 - K i BB startera: linia O/U strikeouts / walks allowed; outs recorded (albo srednie IP) -> IP startera; K%/BB% ataku rywala: mlb_idx albo swiezy fangraphs.
STALE ZMIERZONE: dyspersje var/mean z 02.09.2026 (2084 meczow) - w nowym sezonie po ~miesiacu przemierzyc na komputerze (DANE_MLB["pomiar"]).
dyspersje pojedynczego miotacza (K 1,15, outy 1,15, BB 1,11) sa NIEZMIERZONE - nie opierac na nich waskiego bina.
"""
