MLB_CICHO = False


def _mlb_say(txt):
    if not MLB_CICHO:
        print("[mlb] " + txt)


def _mlb_ok(p, nazwa=""):
    s = sum(p)
    assert abs(s - 1) < 1e-6 and min(p) >= -1e-12, (nazwa, s)
    return [float(x) for x in p]


# ------------------------------------------------------------------------------------------ rozklady --
def _mlb_nb(mean, vm, kmax=60):
    """pmf ujemnego dwumianu o sredniej mean i var/mean = vm (vm<=1 -> Poisson); jak rynki.nb_pmf."""
    if mean <= 0:
        raise ValueError("srednia <= 0")
    if vm <= 1 + 1e-9:
        lm = math.log(mean)
        pmf = [math.exp(-mean + k * lm - math.lgamma(k + 1)) for k in range(kmax + 1)]
    else:
        p = 1.0 / vm
        r = mean / (vm - 1.0)
        pmf = [math.exp(math.lgamma(k + r) - math.lgamma(r) - math.lgamma(k + 1) + r * math.log(p) + k * math.log1p(-p))
               for k in range(kmax + 1)]
    s = sum(pmf)
    return [x / s for x in pmf]


def _mlb_biny(pmf, kraw):
    """pmf (po calkowitych) -> biny o gornych krawedziach kraw + ostatni otwarty; jak rynki.to_bins."""
    out, lo = [], -1
    for k in kraw:
        out.append(sum(pmf[lo + 1:k + 1]))
        lo = k
    out.append(sum(pmf[kraw[-1] + 1:]))
    t = sum(out)
    return [x / t for x in out]


def _mlb_mix(mean, vm, kraw, sigma, kmax=60):
    """Niepewnosc sredniej: mieszanka NB przy sredniej x (1-sigma | 1 | 1+sigma), wagi 0,25 / 0,5 / 0,25."""
    assert 0 <= sigma < 1
    out = [0.0] * (len(kraw) + 1)
    for mult, w in ((1 - sigma, .25), (1.0, .5), (1 + sigma, .25)):
        d = _mlb_biny(_mlb_nb(mean * mult, vm, kmax), kraw)
        out = [o + w * x for o, x in zip(out, d)]
    t = sum(out)
    return _mlb_ok([x / t for x in out])


def _mlb_fit(pts, vm, kmax=60, lo=0.2, hi=40.0):
    """Srednia NB (dyspersja vm) dopasowana najmniejszymi kwadratami do ogonow rynku pts = [(prog, P(X>=prog))]."""
    if not pts:
        raise ValueError("brak punktow rynkowych do dopasowania")

    def err(m):
        pmf = _mlb_nb(m, vm, kmax)
        return sum((sum(pmf[t:]) - p) ** 2 for t, p in pts)
    for _ in range(200):
        a, b = lo + (hi - lo) / 3, hi - (hi - lo) / 3
        if err(a) < err(b):
            hi = b
        else:
            lo = a
    return (lo + hi) / 2


def _mlb_pts(linie):
    """[(linia, p_over[, n])] -> [(ceil(linia), p)]: P(X >= ceil(linia)). Linie calkowite pomijane (push); ta sama linia 2x = srednia."""
    acc = {}
    for t in linie:
        l, p = float(t[0]), float(t[1])
        if abs(l - round(l)) < 1e-9:
            continue
        acc.setdefault(math.ceil(l), []).append(p)
    if not acc:
        raise ValueError("brak linii polowkowych (8.5, nie 9) - linie calkowite maja push")
    return sorted((k, sum(v) / len(v)) for k, v in acc.items())


def mlb_kraw(etykiety):
    """Etykiety binow ["0-2","3","4","5","6","7+"] -> gorne krawedzie [2,3,4,5,6]. Ostatni bin musi byc otwarty ("7+")."""
    assert etykiety[-1].strip().endswith("+"), "ostatni bin ma byc otwarty (np. 7+)"
    kr, prev = [], None
    for e in etykiety[:-1]:
        c = [int(x) for x in e.strip().split("-")]
        assert prev is None or c[0] == prev + 1, "luka miedzy binami: %s" % (etykiety,)
        prev = c[-1]
        kr.append(prev)
    assert int(etykiety[-1].strip()[:-1]) == prev + 1, "luka przed ostatnim binem: %s" % (etykiety,)
    return kr


def mlb_biny(srednia, vm, kraw, sigma=0.22, kmax=60):
    """Ogolnie: srednia + dyspersja var/mean -> biny (mieszanka NB, sigma wzgledna sredniej)."""
    return _mlb_mix(srednia, vm, kraw, sigma, kmax)


def mlb_stan():
    """Pokazuje wbudowane pomiary (data, srednie, var/mean)."""
    D = DANE_MLB
    print("pomiar %s, %d meczow; druzyny (K%%/BB%%) stan %s" % (D["pomiar"]["data"], D["pomiar"]["meczow"], D["idx_druzyn"]["stan"]))
    for k in D["vm"]:
        print("  %-13s srednia %6.2f  var/mean %.3f" % (k, D["srednia"][k], D["vm"][k]))


def mlb_idx(druzyna, metryka, strona="atak"):
    """Wskaznik druzyny wzgledem ligi (1,10 = o 10 % wiecej). metryka: k|bb|hr|2b; strona: atak (batting) | pitching.
    Tabela z ok. 03.09.2026 (skroty jak BettingPros: ATH, CWS, KC, SD, SF, TB, WSH). W NOWYM SEZONIE wziac swiezy K%/BB% druzyny
    (fangraphs/baseball-reference) i podzielic przez liga (DANE_MLB['idx_druzyn'] + liga9). Do K/BB startera: idx = ATAKU RYWALA."""
    return DANE_MLB["idx_druzyn"][strona][druzyna][metryka]


# ------------------------------------------------------------------------------------ linie i kursy --
def mlb_linie(wiersze):
    """Kursy kilku ksiazek -> [(linia, p_over, liczba_ksiazek)]. wiersze = [(linia, kurs_over, kurs_under), ...] (kursy amerykanskie,
    po jednym wierszu na ksiazke i linie). Devig dwustronny PER KSIAZKA, potem mediana per linia - jak rynki.points."""
    per = {}
    for w in wiersze:
        per.setdefault(float(w[0]), []).append(devig(w[1], w[2]))
    return sorted((l, float(np.median(v)), len(v)) for l, v in per.items())


def _mlb_imp(c):
    return 100 / (c + 100) if c > 0 else -c / (-c + 100)


def mlb_anytime(gracze):
    """Propsy anytime (HR, 2B) -> [(nazwa, p, liczba_ksiazek)] do mlb_hr_mecz / mlb_double_mecz.
    gracze = [(nazwa, [(kurs_yes, kurs_no_albo_None), ...])], po jednej parze na ksiazke. Gdy ksiazka nie wystawia 'No', p = implikowane x
    mediana mnoznika devigu z par dwustronnych tego samego rynku (metoda Quizu #10); bez zadnej pary dwustronnej mnoznik 0,925 (Quiz #9)
    - wtedy p jest PRZYBLIZONE, napisz to w raporcie. Mediana po ksiazkach per gracz."""
    mult = sorted(devig(y, n) / _mlb_imp(y) for _, ps in gracze for y, n in ps if n is not None)
    med = mult[len(mult) // 2] if mult else 0.925
    if not mult:
        _mlb_say("[!] zadnej pary Yes/No - devig przyblizony mnoznikiem 0,925 (metoda Quizu #9, niezweryfikowana)")
    out = []
    for nazwa, ps in gracze:
        v = [devig(y, n) if n is not None else _mlb_imp(y) * med for y, n in ps]
        out.append((nazwa, float(np.median(v)), len(v)))
    return out


# ---------------------------------------------------------------------------------------------- runy --
def mlb_srednia_runow(linie, druzyna=False, vm=None):
    """Srednia runow dopasowana do linii: total meczu (druzyna=False) albo team total (druzyna=True)."""
    vm = vm or DANE_MLB["vm"]["runy_druzyny" if druzyna else "runy_razem"]
    return _mlb_fit(_mlb_pts(linie), vm, 30 if druzyna else 60)


def mlb_runy_druzyny(linie, kraw, vm=None, sigma=None):
    """Runy jednej druzyny z team totalu. linie = [(linia, p_over, n)]. sigma: 0,12 przy >= 2 liniach, 0,18 przy jednej (cienka kotwica)."""
    pts = _mlb_pts(linie)
    vm = vm or DANE_MLB["vm"]["runy_druzyny"]
    m = _mlb_fit(pts, vm, 30)
    sigma = sigma if sigma is not None else (0.12 if len(pts) >= 2 else 0.18)
    _mlb_say("team total: %d linii -> srednia %.2f runow (sigma %.2f, var/mean %.3f)" % (len(pts), m, sigma, vm))
    return _mlb_mix(m, vm, kraw, sigma, 30)


def mlb_runy_total(linie, kraw, vm=None, sigma=None):
    """Runy w meczu z drabinki totalu. sigma: 0,10 przy >= 2 liniach, 0,15 przy jednej."""
    pts = _mlb_pts(linie)
    vm = vm or DANE_MLB["vm"]["runy_razem"]
    m = _mlb_fit(pts, vm, 60)
    sigma = sigma if sigma is not None else (0.10 if len(pts) >= 2 else 0.15)
    _mlb_say("total: %d linii -> srednia %.2f runow (sigma %.2f, var/mean %.3f)" % (len(pts), m, sigma, vm))
    return _mlb_mix(m, vm, kraw, sigma, 60)


def mlb_kontrola_totalu(linie_total, linie_tt_a, linie_tt_b):
    """Dwa niezalezne odczyty tego samego rynku: total meczu vs suma team totals. Zwraca (total, suma, rozjazd w %)."""
    tg = mlb_srednia_runow(linie_total)
    s = mlb_srednia_runow(linie_tt_a, True) + mlb_srednia_runow(linie_tt_b, True)
    roz = abs(tg - s) / tg * 100
    _mlb_say("kontrola: total %.2f vs suma team totals %.2f, rozjazd %.1f %%%s" % (tg, s, roz, "  [!] duzy rozjazd" if roz > 10 else ""))
    return tg, s, roz


# ------------------------------------------------------------------------------------- HR i doubles --
def _mlb_props(props):
    out = []
    for t in props:
        if isinstance(t, (int, float)):
            out.append((float(t), 3))
        elif len(t) == 3:
            out.append((float(t[1]), int(t[2])))
        else:
            out.append((float(t[1]), 3) if isinstance(t[0], str) else (float(t[0]), int(t[1])))
    return out


def mlb_lambda_propsow(props, rynek="hr", total_meczu=None):
    """Lambda meczowa = mnoznik x suma 18 NAJWYZSZYCH surowych p anytime (HR 0,894; 2B 0,891). Bez recal k=1,14 - to byloby podwojne liczenie.
    props = lista p albo (p, n_ksiazek) albo (nazwa, p, n) - np. z mlb_anytime. Propsy z >= 3 ksiazek maja pierwszenstwo; brakujace sloty
    dopelnia sie najlepszymi cienkimi (rynki.lam_top_fill). total_meczu = srednia runow z mlb_srednia_runow (niezalezna kontrola)."""
    assert rynek in ("hr", "doubles")
    pp = _mlb_props(props)
    if len(pp) < 16:
        raise ValueError("tablica ma tylko %d propsow - za malo na 18 miejsc w lineupie; poczekaj na pelna liste" % len(pp))
    grube = sorted((p for p, n in pp if n >= 3), reverse=True)
    ps, uzyte = grube[:18], 0
    if len(ps) < 18:
        dob = sorted((p for p, n in pp if n < 3), reverse=True)[:18 - len(ps)]
        uzyte = len(dob)
        ps = sorted(ps + dob, reverse=True)[:18]
    mn = DANE_MLB["mnoznik_lambda"][rynek]
    lam = sum(ps) * mn
    baz = DANE_MLB["srednia"][rynek]
    _mlb_say("lambda %s = %.2f (suma top-18 %.2f x %.3f; %d propsow >=3 ksiazki + %d dopelniajacych)" % (rynek, lam, sum(ps), mn, len(grube[:18]), uzyte))
    if abs(lam - baz) / baz > 0.25:
        _mlb_say("[!] odchylenie od baseliny %.2f > 25 %% - sprawdz" % baz)
    if uzyte > 6:
        _mlb_say("[!] tablica niedojrzala: tylko %d propsow z >=3 ksiazek, %d dopelnionych cienkimi; mnozniki mierzono na kursach ZAMKNIECIA - powtorz pozniej" % (len(grube[:18]), uzyte))
    if total_meczu:
        oczek = baz * total_meczu / DANE_MLB["srednia"]["runy_razem"]
        roz = (lam - oczek) / oczek
        _mlb_say("kontrola z totalu %.2f runow -> oczekiwane %.2f, model %.2f (%+.0f %%)%s" % (total_meczu, oczek, lam, roz * 100, "  [!] rozjazd > 20 %" if abs(roz) > 0.2 else ""))
    return lam


def mlb_hr_mecz(props, kraw, total_meczu=None, vm=None, sigma=0.22):
    """Ile HR w meczu: NB o lambdzie z mlb_lambda_propsow(rynek 'hr'), var/mean 1,260, sigma 0,22."""
    lam = mlb_lambda_propsow(props, "hr", total_meczu)
    return _mlb_mix(lam, vm or DANE_MLB["vm"]["hr"], kraw, sigma, 60)


def mlb_double_mecz(props, kraw, total_meczu=None, vm=None, sigma=0.22):
    """Ile doubli w meczu: NB o lambdzie z mlb_lambda_propsow(rynek 'doubles'), var/mean 1,171, sigma 0,22."""
    lam = mlb_lambda_propsow(props, "doubles", total_meczu)
    return _mlb_mix(lam, vm or DANE_MLB["vm"]["doubles"], kraw, sigma, 60)


def _mlb_recal(p):
    k = DANE_MLB["k_potegowy"]
    return p ** k / (p ** k + (1 - p) ** k) if p else p


def mlb_hr_binarne(gracze, potwierdzone=False, dnp=None):
    """Czy KTORYS z graczy uderzy HR -> [P(Yes), P(No)]. gracze = [(p_surowe, w_skladzie, hr_na_pa), ...]
    p_surowe = devigowane p anytime HR z rynku (mlb_anytime) albo None; hr_na_pa = HR/PA gracza w sezonie (potrzebne tylko poza skladem).
    Gracz w skladzie z propsem: recal k=1,14 (devig potegowy POJEDYNCZEGO propsu). W skladzie bez propsu: 0. Poza skladem (cena = spozniona linia,
    ODRZUC): zmiennik = 0,25 x HR/PA. Przy skladzie projected kazdy dostaje mnoznik (1 - 0,07) - 7 % propsow dotyczy graczy, ktorzy nie weszli do meczu.
    Drukuje tez p(Yes) surowo - modalne 'Nie' przegralo 6 razy na 8, raportuj obie liczby."""
    dnp = (0.0 if potwierdzone else DANE_MLB["p_dnp"]) if dnp is None else dnp
    sur, pop = [], []
    for p, w_skladzie, hr_pa in gracze:
        if w_skladzie:
            p0 = float(p) if p is not None else 0.0
        else:
            p0 = DANE_MLB["p_zmiennik"] * float(hr_pa or 0.0)
        sur.append(p0)
        pop.append((1 - dnp) * _mlb_recal(p0))
    yes = 1.0 - math.prod(1 - x for x in pop)
    yes_sur = 1.0 - math.prod(1 - x for x in sur)
    _mlb_say("HR binarne: p(Yes) = %.3f po k=1,14 i DNP %.0f %%, %.3f surowo (bez obu)%s" % (
        yes, dnp * 100, yes_sur, "" if potwierdzone else "  [!] sklady projektowane - wpiete DNP"))
    return _mlb_ok([yes, 1 - yes])


# ---------------------------------------------------------------------------------------------- hity --
def _mlb_binom(n, q):
    return [math.comb(n, k) * q ** k * (1 - q) ** (n - k) for k in range(n + 1)]


def _mlb_fit_binom(pts, n, lo=0.005, hi=0.7):
    """q (P(hit) na PA) tak, by ogony dwumianu Bin(n, q) pasowaly do WSZYSTKICH polowkowych progow rynku (0.5 i 1.5)."""
    def err(q):
        pmf = _mlb_binom(n, q)
        return sum((sum(pmf[t:]) - p) ** 2 for t, p in pts)
    for _ in range(200):
        a, b = lo + (hi - lo) / 3, hi - (hi - lo) / 3
        if err(a) < err(b):
            hi = b
        else:
            lo = a
    return (lo + hi) / 2


def mlb_hity_dwoch(gracze, kraw, potwierdzone=False, dnp=None):
    """Ile hitow lacznie zaliczy dwoch graczy. gracze = [(linie_hitow, slot), (linie_hitow, slot)];
    linie_hitow = [(0.5, p_over), (1.5, p_over)] - podaj OBIE linie, jesli ksiazki je kwotuja (modalna linia 1.5 to NIE P(>=1) - blad z Quizu #12);
    slot = miejsce w lineupie 1-9 (brak -> 5). PA = round(PA_SLOT[slot]) (np. slot 1-2 -> 5 PA, 3-9 -> 4 PA). Dwumian dopasowany do linii,
    przy skladzie projected kazdy gracz z prawd. 0,07 nie wchodzi do meczu (0 hitow), splot obu graczy."""
    assert len(gracze) == 2
    dnp = (0.0 if potwierdzone else DANE_MLB["p_dnp"]) if dnp is None else dnp
    pmfs = []
    for linie, slot in gracze:
        sl = int(slot or 5)
        n = int(round(DANE_MLB["pa_slot"][sl - 1]))
        q = _mlb_fit_binom(_mlb_pts(linie), n)
        pmf = _mlb_binom(n, q)
        p1 = 1 - pmf[0]
        pmf = [(1 - dnp) * x + (dnp if i == 0 else 0.0) for i, x in enumerate(pmf)]
        pmfs.append(pmf)
        _mlb_say("hity: slot %d, %d PA, q=%.3f, P(1+)=%.3f (bez DNP %.3f)%s" % (
            sl, n, q, 1 - pmf[0], p1, "  [!] P(1+) < 0.45 dla gracza z lineupu - sprawdz linie" if p1 < 0.45 else ""))
    joint = [0.0] * (len(pmfs[0]) + len(pmfs[1]) - 1)
    for i, x in enumerate(pmfs[0]):
        for j, y in enumerate(pmfs[1]):
            joint[i + j] += x * y
    return _mlb_ok(_mlb_biny(joint, kraw))


# -------------------------------------------------------------------------------------- K i walki --
def _mlb_ip(s, vm_out):
    if s.get("ip") is not None:
        return float(s["ip"])
    if s.get("outy"):
        return _mlb_fit(_mlb_pts(s["outy"]), vm_out, 40, 6.0, 27.0) / 3.0
    _mlb_say("[!] brak IP startera - przyjete 5,2")
    return 5.2


def _mlb_miotacze(starterzy, klucz, vm_st, kmax_st, lo_st, hi_st, vm_out, pen9):
    """Suma lambd obu starterow (z ich linii) + bullpen kotwiczony we wskazniku ataku RYWALA. Zwraca (lambda, opis, min_ksiazek)."""
    assert len(starterzy) == 2
    lam, opis, nk = 0.0, [], []
    for s in starterzy:
        w = s[klucz]
        if isinstance(w, (int, float)):
            ls = float(w)
        else:
            ls = _mlb_fit(_mlb_pts(w), vm_st, kmax_st, lo_st, hi_st)
            nk.append(max([t[2] for t in w if len(t) > 2] or [0]))
        ip = _mlb_ip(s, vm_out)
        ip_pen = max(DANE_MLB["outy_druzyny"] / 3.0 - ip, 0.5)
        idx = s.get("idx")
        if idx is None:
            _mlb_say("[!] brak 'idx' (wskaznik ataku rywala) - przyjete 1.00")
            idx = 1.0
        lam += ls + ip_pen * pen9 * idx / 9.0
        opis.append("%s %.2f + bullpen %.1f IP @ %.2f/9" % (s.get("nazwa", "starter"), ls, ip_pen, pen9 * idx))
    return lam, "; ".join(opis), (min(nk) if nk else None)


def mlb_strikeouty(starterzy, kraw, vm=None, sigma=0.15):
    """Ile K w meczu: propsy K obu starterow + bullpen. starter = {"k": linie [(4.5, p_over), ...] albo liczba lambda, "outy": linie outs recorded
    albo "ip": oczekiwane IP, "idx": K% ataku RYWALA / K% ligi, "nazwa": opcjonalnie}. Bullpen = (8,83 - IP startera, min 0,5) x 9,4 K/9 x idx
    - NIE dziedziczy K/9 startera (pudla w Quizach #9 i #10). Mieszanka NB var/mean 1,039, sigma 0,15. Wynik ponizej baseliny 16,70 uzasadnij osobno."""
    D = DANE_MLB
    lam, opis, _ = _mlb_miotacze(starterzy, "k", D["vm_miotacz"]["k"], 20, 1.0, 15.0, D["vm_miotacz"]["out"], D["k9_bullpen"])
    vm = vm or D["vm"]["strikeouty"]
    _mlb_say("lambda K = %.2f (var/mean %.3f): %s" % (lam, vm, opis))
    if lam < D["srednia"]["strikeouty"]:
        _mlb_say("[!] ponizej baseliny %.2f - uzasadnij osobno (tryb porazki Quizow #9/#10)" % D["srednia"]["strikeouty"])
    return _mlb_mix(lam, vm, kraw, sigma, 60)


def mlb_walki(starterzy, kraw, vm=None, sigma=None, min_ksiazek=None):
    """Ile BB w meczu: propsy walkow obu starterow + bullpen (3,9 BB/9 x idx BB% ataku rywala). starter = {"bb": linie albo lambda, "outy"/"ip", "idx"}.
    sigma zalezy od grubosci kotwicy: 0,35 gdy props z < 3 ksiazek (min_ksiazek; brak informacji = 0,35), 0,18 przy >= 3. Mieszanka NB var/mean 1,348.
    Lambda > 10 % ponizej baseliny 6,75 -> ostrzezenie (Quiz #13: 5,56 przeszlo bez slowa, wypadlo 11). Zrodlo bez rynku: mlb_walki_bez_rynku."""
    D = DANE_MLB
    lam, opis, nk = _mlb_miotacze(starterzy, "bb", D["vm_miotacz"]["bb"], 12, 0.3, 8.0, D["vm_miotacz"]["out"], D["bb9_bullpen"])
    n_ks = min_ksiazek if min_ksiazek is not None else nk
    if sigma is None:
        sigma = 0.35 if (n_ks is None or n_ks < 3) else 0.18
    vm = vm or D["vm"]["walki"]
    _mlb_say("lambda BB = %.2f (sigma %.2f, var/mean %.3f, min %s ksiazek): %s" % (lam, sigma, vm, n_ks, opis))
    if lam < D["srednia"]["walki"] * 0.90:
        _mlb_say("[!!] lambda %.2f jest %.0f %% PONIZEJ baseliny %.2f - uzasadnij osobno albo podciagnij do srednich sezonowych (mlb_bez_rynku)" % (
            lam, 100 * (1 - lam / D["srednia"]["walki"]), D["srednia"]["walki"]))
    return _mlb_mix(lam, vm, kraw, sigma, 60)


# ----------------------------------------------------------------------------------------- bez rynku --
def _mlb_strona(met, bat, pit, starter, park):
    """Oczekiwana liczba zdarzen jednej strony (atak bat vs miotacze pit); jak audyt-bezrynku.strona. bat, pit = skrot z tabeli albo wskaznik (liczba)."""
    D = DANE_MLB
    bi = bat if isinstance(bat, (int, float)) else mlb_idx(bat, met, "atak")
    pi = pit if isinstance(pit, (int, float)) else mlb_idx(pit, met, "pitching")
    liga9 = D["liga9"][met]
    if met == "2b":
        return liga9 * bi * pi * park
    pole = {"k": "k9", "bb": "bb9", "hr": "hr9"}[met]
    if starter and starter.get(pole):
        s_idx = float(starter[pole]) / liga9
        ip_s = min(max(float(starter.get("ip_na_start") or 4.6), 3.5), 7.0)
    else:
        s_idx, ip_s = pi, 5.2
    ip_pen = max(D["outy_druzyny"] / 3.0 - ip_s, 0.5)
    pen9 = {"k": D["k9_bullpen"], "bb": D["bb9_bullpen"], "hr": liga9 * pi}[met]
    return (ip_s * liga9 * s_idx / 9.0 + ip_pen * pen9 / 9.0) * bi * park


def mlb_bez_rynku(metryka, strony, kraw, park=1.0, sigma=0.60, vm=None):
    """Sciezka AWARYJNA, gdy rynek propsow jeszcze nie istnieje (K, BB, HR, 2B w meczu). metryka = "k"|"bb"|"hr"|"2b".
    strony = [(atak, pitching, starter), (atak, pitching, starter)] - atak = druzyna palkarzy (skrot jak 'CWS' albo wskaznik liczbowy),
    pitching = druzyna miotaczy, starter = {"k9":..,"bb9":..,"hr9":..,"ip_na_start": IP/GS} z sezonu albo None. park = PIERWIASTEK z park factora
    (PF 1,10 -> 1,049). Wynik x zmierzony mnoznik (backtest 585-614 meczow: HR 1,013, 2B 0,964, K 0,970, BB 0,986). Estymator jest nieobciazony,
    ale slabo rozroznia mecze (r = 0,21-0,46), wiec sigma 0,60 (Quiz #11: sigma 0,30 zwinela pytanie do jednego bina i kosztowalo). Rynek, gdy jest, ZAWSZE wygrywa."""
    D = DANE_MLB
    assert metryka in ("k", "bb", "hr", "2b")
    lam = sum(_mlb_strona(metryka, a, p, s, park) for a, p, s in strony) * D["bezrynku"][metryka]
    nvm = {"k": "strikeouty", "bb": "walki", "hr": "hr", "2b": "doubles"}[metryka]
    vm = vm or D["vm"][nvm]
    _mlb_say("BEZ RYNKU %s: lambda %.2f (baselina %.2f), sigma %.2f, var/mean %.3f" % (metryka, lam, D["srednia"][nvm], sigma, vm))
    return _mlb_mix(lam, vm, kraw, sigma, 60)


