_PILKA_LG = np.array([math.lgamma(k + 1) for k in range(200)])


# ------------------------------------------------------------------ pomocnicze ---
def _pilka_ok(p, nazwa=""):
    p = [float(x) for x in p]
    assert min(p) >= -1e-12, (nazwa, "ujemne", p)
    assert abs(sum(p) - 1) < 1e-6, (nazwa, "suma", sum(p))
    return p


def _pilka_kraw(kraw):
    kraw = [int(k) for k in kraw]
    assert kraw == sorted(set(kraw)) and len(kraw) >= 1, ("kraw ma byc rosnaca lista calkowitych", kraw)
    return kraw


def _pilka_bin_pmf(pmf, kraw):
    """pmf (po 0,1,2,...) -> biny; kraw = gorne krawedzie (wlacznie) bez ostatniego otwartego."""
    kraw = _pilka_kraw(kraw)
    assert kraw[-1] < len(pmf), "pmf za krotkie dla kraw"
    out, lo = [], -1
    for k in kraw:
        out.append(float(sum(pmf[lo + 1:k + 1])))
        lo = k
    out.append(float(sum(pmf[kraw[-1] + 1:])))
    return out


def _pilka_imp(c):
    """kurs amerykanski -> p z marza"""
    c = float(c)
    return 100 / (c + 100) if c > 0 else -c / (-c + 100)


def _pilka_pois(lam, n=40):
    k = np.arange(n)
    return np.exp(-lam + k * math.log(lam) - _PILKA_LG[:n])


def _pilka_nb(lam, vm, n=None):
    """NB o sredniej lam i var/mean = vm (vm <= 1 -> Poisson, bo NB nie umie niedodyspersji); znormalizowane na [0, n)."""
    assert 0 < lam <= 45, ("lam poza zakresem", lam)
    n = min(n or max(40, int(lam * 4 + 30)), 200)
    if vm <= 1.0001:
        p = _pilka_pois(lam, n)
    else:
        r = lam / (vm - 1.0)
        q = 1.0 / vm
        k = np.arange(n)
        p = np.exp(np.array([math.lgamma(x + r) for x in k]) - math.lgamma(r) - _PILKA_LG[:n] + r * math.log(q) + k * math.log1p(-q))
    return p / p.sum()


def _pilka_mieszaj(lam, vm, n, sigma):
    """3-punktowa niepewnosc sredniej: (1-sigma, .25), (1, .5), (1+sigma, .25)."""
    if not sigma:
        return _pilka_nb(lam, vm, n)
    return sum(w * _pilka_nb(lam * m, vm, n) for m, w in ((1 - sigma, .25), (1.0, .5), (1 + sigma, .25)))


def _pilka_tilt(lam, nu, n=30):
    """Poisson podniesiony do potegi nu (nu > 1 = niedodyspersja, jak gole)."""
    k = np.arange(n)
    w = np.exp((-lam + k * math.log(lam) - _PILKA_LG[:n]) * nu)
    return w / w.sum()


def _pilka_tilt_vm(lam, vm, n=30):
    lo, hi = 1.0, 3.0
    k = np.arange(n)
    for _ in range(60):
        nu = (lo + hi) / 2
        d = _pilka_tilt(lam, nu, n)
        sr = float((k * d).sum())
        if float(((k - sr) ** 2 * d).sum()) / sr > vm:
            lo = nu
        else:
            hi = nu
    return _pilka_tilt(lam, (lo + hi) / 2, n)


def _pilka_Phi(x):
    return 0.5 * (1 + math.erf(x / math.sqrt(2))) if np.isfinite(x) else (1.0 if x > 0 else 0.0)


def _pilka_norm_biny(mu, sd, kraw):
    """P(bin) dla N(mu, sd); bin 'a-b' calkowitych % = przedzial (a-0,5; b+0,5]."""
    kraw = _pilka_kraw(kraw)
    gr = [-np.inf] + [k + 0.5 for k in kraw] + [np.inf]
    return [_pilka_Phi((b - mu) / sd) - _pilka_Phi((a - mu) / sd) for a, b in zip(gr[:-1], gr[1:])]


# ------------------------------------------------------------- 1X2 i roznica ---
def pilka_1x2(ksiazki):
    """Zwyciezca meczu. ksiazki = [(kurs_A, kurs_B, kurs_remis), ...] kursy AMERYKANSKIE po jednej ksiazce (A i B w kolejnosci binow
    quizu; z kursow dziesietnych: >= 2 -> (d-1)*100, < 2 -> -100/(d-1)). Metoda komputera: devig proporcjonalny PER KSIAZKA,
    mediana per wynik, normalizacja sumy median. Zwraca [A, B, Remis]. Ile ksiazek: im wiecej tym lepiej (komputer 12-14)."""
    assert len(ksiazki) >= 1
    pa = np.array([[_pilka_imp(c) for c in k] for k in ksiazki])
    pa = pa / pa.sum(axis=1, keepdims=True)
    med = np.median(pa, axis=0)
    return _pilka_ok(med / med.sum(), "1x2")


def pilka_roznica(p_wygra, p_roznica2):
    """'Czy X wygra roznica > 1 gola': [Yes, By exactly 1, No].
    p_wygra = P(X wygra) z 1X2 (pilka_1x2, wynik dla X). p_roznica2 = P(X wygra o >= 2 gole) z rynku handicapu: albo liczba, albo
    [(p, liczba_ksiazek), ...] (srednia wazona ksiazkami). Skad p_roznica2 (komputer, rynek BettingPros 173 'three-way spread'):
      * handicap 3-DROGOWY -2: etykiety 'X -2' (= roznica >= 3), 'Draw' (= dokladnie 2), 'Y +2'; po devigu 3 wyjsc
        P(roznica >= 2) = P('X -2') + P('Draw');
      * handicap AZJATYCKI X -1,5 (2 wyjscia, devig): P(roznica >= 2) = P('X -1,5').
    By exactly 1 = p_wygra - P(roznica>=2); No = 1 - p_wygra (remis albo porazka)."""
    if isinstance(p_roznica2, (list, tuple)) and p_roznica2 and isinstance(p_roznica2[0], (list, tuple)):
        p2 = sum(p * k for p, k in p_roznica2) / sum(k for _, k in p_roznica2)
    else:
        p2 = float(p_roznica2)
    assert 0 <= p2 <= p_wygra <= 1, ("P(roznica>=2) musi byc <= P(wygra)", p2, p_wygra)
    return _pilka_ok([p2, p_wygra - p2, 1 - p_wygra], "roznica")


def pilka_roznica_skellam(lam_a, lam_b):
    """Zapas bez handicapu: [Yes, By exactly 1, No] z niezaleznych Poissonow (lam z team totals / 1X2 + total). Zgodnosc z rynkiem
    handicapu ok. 2 pp (sprawdzone 03.11) - uzywaj tylko, gdy brak handicapu."""
    n = 25
    pa, pb = _pilka_pois(lam_a, n), _pilka_pois(lam_b, n)
    roz = np.zeros(2 * n - 1)
    for i in range(n):
        roz[i - np.arange(n) + n - 1] += pa[i] * pb
    d = np.arange(-(n - 1), n)
    roz = roz / roz.sum()
    return _pilka_ok([roz[d >= 2].sum(), roz[d == 1].sum(), roz[d <= 0].sum()], "skellam")


# --------------------------------------------------------------------- gole ---
def _pilka_gole(linia, p_over, vm=None):
    """(pmf tilt-Poissona vm 0,902 dopasowany do P(suma > linia) = p_over, P0 z CZYSTEGO Poissona, srednia).
    P0 z Poissona, bo tilt zaniza zera o 17 % (zmierzone 20.10 na 10 liga-sezonach)."""
    vm = vm or DANE_PILKA["gole"]["vm"]
    assert 0 < p_over < 1
    assert abs(linia * 2 - round(linia * 2)) < 1e-9 and linia != int(linia), "linia ma byc polowkowa (2,5; 3,5...)"
    prog = int(math.ceil(linia))
    lo, hi = 0.5, 8.0
    for _ in range(60):
        mid = (lo + hi) / 2
        if float(_pilka_tilt_vm(mid, vm)[prog:].sum()) < p_over:
            lo = mid
        else:
            hi = mid
    d = _pilka_tilt_vm((lo + hi) / 2, vm)
    lo, hi = 0.3, 8.0
    for _ in range(60):
        mid = (lo + hi) / 2
        if 1 - sum(math.exp(-mid) * mid ** k / math.factorial(k) for k in range(prog)) < p_over:
            lo = mid
        else:
            hi = mid
    P0 = math.exp(-(lo + hi) / 2)
    return d, P0, float((np.arange(len(d)) * d).sum())


def pilka_gole(linia, p_over, kraw, popraw_p0=True):
    """Suma goli w meczu. linia + p_over = linia totalu z NAJWIEKSZA liczba ksiazek i P(Over) po devigu (np. 3,5 i 0,442).
    tilt-Poisson (var/mean 0,902 zmierzone na 787 meczach EPL), P(0) z czystego Poissona (popraw_p0=True; stan 04.11, 10-14 i 10-21
    liczone bez korekty P0 - roznica < 1 pp). Bin 'Remis' w quizie (21.10: 0/1/Remis/3...) = 2 gole: kraw [0,1,2,3,4,5,6].
    Gdy rynek ma kilka linii, bierz te z najwieksza liczba ksiazek."""
    d, P0, _ = _pilka_gole(linia, p_over)
    d = np.array(d)
    if popraw_p0:
        d[1:] *= (1 - P0) / d[1:].sum()
        d[0] = P0
    return _pilka_ok(_pilka_bin_pmf(list(d), kraw), "gole")


def pilka_minuta_gola(linia, p_over, kraw, p0=None):
    """Minuta 1. gola MECZU. P(brak gola do minuty t) = P0 ** G(t); G = skumulowany hazard 1. gola (3 082 meczow fotmob, walidacja
    poza proba chi2 5,7 na 7 binach), P0 = P(0 goli) z czystego Poissona dopasowanego do totalu (linia, p_over) albo podane p0.
    kraw = gorne krawedzie minut bez ostatniego binu 'inne/Other' (np. 1-7/8-14/.../50-70/Other -> [7,14,23,34,49,70]); ostatni bin
    = brak gola do ostatniej krawedzi (lacznie z golem pozniej i 0:0). 45+x liczone jako 45, 90+x jako 90."""
    kraw = _pilka_kraw(kraw)
    assert kraw[0] >= 1 and kraw[-1] <= 90
    if p0 is None:
        p0 = _pilka_gole(linia, p_over)[1]
    G = DANE_PILKA["minuta_gola"]["G"]
    przezyw = lambda t: p0 ** G[t] if t >= 1 else 1.0
    lo, out = 0, []
    for k in kraw:
        out.append(przezyw(lo) - przezyw(k))
        lo = k
    out.append(przezyw(lo))
    return _pilka_ok(out, "minuta_gola")


def _pilka_minuta_proces(N, Fc, skala, kraw):
    kraw = _pilka_kraw(kraw)
    assert kraw[0] >= 1 and kraw[-1] <= 90
    S = lambda t: math.exp(-N * skala * Fc[t]) if t >= 1 else 1.0
    lo, out = 0, []
    for k in kraw:
        out.append(S(lo) - S(k))
        lo = k
    out.append(S(lo))
    return out


def pilka_minuta_rozny(rogi_druzyny, kraw, skala=None):
    """Minuta 1. rzutu roznego DRUZYNY. Proces Poissona na zmierzonym profilu minut (3 969 rogow z minutami, komentarz Opta/ESPN),
    N = oczekiwana liczba rogow druzyny w tym meczu (pilka_lam(..., 'rozne', ...) albo srednia druzyny z fbref skorygowana o rywala),
    skala 0,876 (rogi chodza seriami; kalibracja na lidze chi2 0,63 na 5 binach). kraw: 1-4/5-8/9-13/14-20/21-31/Other -> [4,8,13,20,31]."""
