_nba_erfc = np.frompyfunc(math.erfc, 1, 1)


def _nba_norm_cdf(z):
    return 0.5 * np.asarray(_nba_erfc(-np.asarray(z, dtype=float) / math.sqrt(2.0)), dtype=float)


def _nba_pmf(mu, vm, kmax):
    """Rozklad Poissona (vm<=1,0001) albo ujemny dwumianowy o sredniej mu i var/mean = vm; ogon dodany do ostatniej komorki."""
    p = np.zeros(kmax + 1)
    if vm <= 1.0001:
        p[0] = math.exp(-mu)
        for k in range(1, kmax + 1):
            p[k] = p[k - 1] * mu / k
    else:
        r, q = mu / (vm - 1.0), 1.0 / vm
        p[0] = q ** r
        for k in range(1, kmax + 1):
            p[k] = p[k - 1] * (k - 1 + r) / k * (1 - q)
    p[-1] += 1 - p.sum()
    return p


def _nba_srednia(pts, vm, kmax):
    """Srednia NB dopasowana do [(linia, p_over, n)] (najmniejsze kwadraty wazone liczba ksiazek), jak nb_srednia na komputerze."""
    def err(m):
        p = _nba_pmf(m, vm, kmax)
        return sum(n * (p[int(math.floor(l)) + 1:].sum() - po) ** 2 for l, po, n in pts)
    lo, hi = 0.2, kmax * 0.8
    for _ in range(100):
        a, b = lo + (hi - lo) / 3, hi - (hi - lo) / 3
        if err(a) < err(b):
            hi = b
        else:
            lo = a
    return (lo + hi) / 2


def _nba_linie(linie):
    """Normalizacja wejscia: (linia, p) albo [(linia, p[, n]), ...] -> [(linia, p, n>=1)], tylko x.5 (jak komputer)."""
    if isinstance(linie, tuple) and len(linie) in (2, 3) and not isinstance(linie[0], (tuple, list)):
        linie = [linie]
    out = []
    for x in linie:
        l, p = float(x[0]), float(x[1])
        n = max(int(x[2]), 1) if len(x) > 2 else 1
        assert 0.0 < p < 1.0, ("p_over poza (0,1)", x)
        if l % 1 == 0.5:
            out.append((l, p, n))
    assert out, "brak linii x.5 - rynek bez polowkowej linii nie jest obslugiwany"
    return out


def _nba_biny(pmf, kraw):
    """pmf po 0..K -> prawdopodobienstwa binow wg kraw (dolne biny wlacznie z krawedzia gorna), normalizacja jak do_binow."""
    pmf = np.asarray(pmf, dtype=float)
    p = np.array(_biny(np.arange(len(pmf)), list(kraw), pmf))
    assert (p >= -1e-12).all()
    p = np.clip(p, 0, None)
    p = p / p.sum()
    assert abs(p.sum() - 1) < 1e-9
    return [float(x) for x in p]


def nba_kraw(etykiety):
    """Etykiety binow z quizu -> kraw. ["0-6","7-8","9","10","11","12-13","14+"] -> [6,8,9,10,11,13]. Sprawdza ciaglosc binow."""
    kraw, nast = [], None
    for i, e in enumerate(etykiety):
        e = e.strip()
        ost = i == len(etykiety) - 1
        if e.endswith("+"):
            assert ost, ("otwarty bin tylko na koncu", e)
            lo = int(e[:-1])
            assert nast is None or lo == nast, ("dziura miedzy binami", e)
            break
        lo, hi = (int(x) for x in e.split("-")) if "-" in e else (int(e), int(e))
        assert nast is None or lo == nast, ("dziura miedzy binami", e, nast)
        kraw.append(hi)
        nast = hi + 1
    assert len(kraw) == len(etykiety) - 1, "ostatni bin ma byc otwarty (np. '14+'); dla zamknietego dodaj sztuczny"
    return kraw


def nba_dnp(x):
    """P(gracz nie zagra -> statystyka 0). Liczba -> ta liczba; "dNN" -> NN %; klucz DANE_NBA["dnp_status"] (raport kontuzji NBA:
    brak = nie ma w raporcie 0,01; P=probable 0,05; Q=questionable 0,35; D=doubtful 0,80; out 1,0) albo DANE_NBA["dnp_prior"]
    (PRZED raportem: b2b_pula_gwiazd 0,13 = 2. mecz back-to-back gwiazdy, zmierzone 64/75 gral; bez_b2b 0,03). Raport NBA: oficjalny PDF
    ligi (ak-static.cms.nba.com/referee/injury/...) albo wyszukiwarka "NBA injury report <data>"; po raporcie uzywaj statusu."""
    if isinstance(x, (int, float)):
        p = float(x)
    elif x in DANE_NBA["dnp_status"]:
        p = DANE_NBA["dnp_status"][x]
    elif x in DANE_NBA["dnp_prior"]:
        p = DANE_NBA["dnp_prior"][x]
    elif x.startswith("d") and x[1:].isdigit():
        p = int(x[1:]) / 100.0
    else:
        raise KeyError("nieznany status DNP: %r" % (x,))
    assert 0.0 <= p <= 1.0
    return p


def nba_kwarta(kolejnosc=("1st", "2nd", "3rd", "4th", "Overtime", "Tie")):
    """Najwyzej punktujaca kwarta (laczne punkty obu druzyn w kwarcie). Empiria 2 sezonow n=2462 (ESPN), bez warunkowania na total
    ani spread (chi2 p 0,47 i 0,19). Overtime: 0/114 dogrywek przebilo najlepsza kwarte -> podloga 0,05 %. Tie = dwie lub wiecej kwart
    z maksimum. Domyslnie 1st 26,0 | 2nd 22,5 | 3rd 28,2 | 4th 16,9 | Overtime 0,05 | Tie 6,3 %. kolejnosc = etykiety wg quizu."""
    K = DANE_NBA["kwarty"]["p"]
    assert set(kolejnosc) == set(K), ("etykiety kwart", kolejnosc)
    p = {b: float(v) for b, v in K.items()}
    p["Overtime"] = max(p["Overtime"], 0.0005)
    s = sum(p.values())
    out = [p[b] / s for b in kolejnosc]
    assert abs(sum(out) - 1) < 1e-9 and min(out) >= 0
    return out


def nba_total(linie, kraw, info=False):
    """Suma punktow meczu. linie = linie totalu [(linia x.5, p_over, ksiazek)] z wyszukiwarki; uzywana jest linia z NAJWIEKSZA liczba
    ksiazek (przy remisie pierwsza). Srednia = linia przesunieta tak, by empiryczna reszta (1151 meczow 2025-26: wynik minus srednia
    z rynku, sd 18,5, z dogrywkami, wygladzona jadrem 2,5 pkt) dawala p_over rynku; ksztalt = ta reszta."""
    T = DANE_NBA["total"]
    pts = _nba_linie(linie)
    l, po, n = max(pts, key=lambda x: x[2])
    r = np.array(T["reszty"], dtype=float)
    r = r - r.mean()
    s = T["jadro"]

    def p_over(mu):
        return float((1.0 - _nba_norm_cdf((l - mu - r) / s)).mean())
    lo, hi = l - 15, l + 15
    for _ in range(60):
        m = (lo + hi) / 2
        lo, hi = (m, hi) if p_over(m) < po else (lo, m)
    mu = (lo + hi) / 2
    k = np.arange(150, 320)
    cdf = np.array([_nba_norm_cdf((x + 0.5 - mu - r) / s).mean() for x in k])
    pmf = np.diff(np.concatenate([[0.0], cdf]))
    pmf[-1] += 1 - pmf.sum()
    full = np.zeros(320)
    full[150:] = pmf
    p = _nba_biny(full, kraw)
    return (p, {"srednia": mu, "linia": l, "n": n}) if info else p


def _nba_rekalibruj(pmf, kal, k_prior=200.0):
    """P(X<=x) = G(F_NB(x)); G = empiryczny PIT klasy sciagniety do identycznosci wagami n/(n+200). Punkty i PRA maja ciezszy
    lewy ogon i lzejszy prawy niz NB (PIT chi2 27 i 22 przy 9 df); zbiorki i asysty pasuja do NB."""
    t = np.linspace(0, 1, 21)
    w = kal["n"] / (kal["n"] + k_prior)
    G = w * np.array(kal["pit_cdf"]) + (1 - w) * t
    F = np.cumsum(pmf)
    Fc = np.interp(np.clip(F, 0, 1), t, G)
    Fc[-1] = 1.0
    out = np.clip(np.diff(np.concatenate([[0.0], Fc])), 0, None)
    return out / out.sum()


def nba_gracz(klasa, linie, kraw, dnp="brak", info=False):
    """Punkty ("pts"), zbiorki ("reb"), asysty ("ast"), PRA ("pra") albo trojki ("fg3") GRACZA. linie = linie propsu tego gracza
    [(linia x.5, p_over, ksiazek)] - dokladnie ten sam rynek co pytanie (PRA = rynek Pts+Reb+Ast, nie suma trzech osobnych).
    Metoda: srednia NB dopasowana do linii (vm zmierzone: reb 1,32 ast 1,26 pts 3,10 pra 2,48 fg3 1,20) x zmierzony mnoznik sredniej
    (rynek zawyza over o 0,5-5 pp: reb 0,960 ast 0,975 pts 0,960 pra 0,965 fg3 0,945) -> rekalibracja ksztaltu PIT (pts i pra).
    dnp = nba_dnp(...) : DNP = statystyka 0 (najnizszy bin). Domyslnie "brak" (1 %, gracz bez wpisu w raporcie); PRZED raportem uzyj
    "b2b_pula_gwiazd" (13 %) w 2. meczu back-to-back gwiazdy albo "bez_b2b" (3 %). Pelne nazwisko gracza (Mitchell = 3 graczy)."""
    kal = DANE_NBA["propsy"][klasa]
    vm = kal["vm"]
    kmax = 90 if klasa == "pra" else 60
    w = _nba_linie(linie)
    mu_r = _nba_srednia(w, vm, kmax)
    mu = kal["m"] * mu_r
    pg = _nba_rekalibruj(_nba_pmf(mu, vm, kmax), kal)
    pd_ = nba_dnp(dnp)
    pmf = (1 - pd_) * pg
    pmf[0] += pd_
    p = _nba_biny(pmf, kraw)
    return (p, {"srednia": mu, "srednia_rynku": mu_r, "vm": vm, "p_dnp": pd_}) if info else p


def _nba_srodowisko(co, liga26, n26):
    """Poziom ligi na POCZATKU sezonu: prior (srednia okien 14 dni 2024-25 i 2025-26) zaktualizowany meczami 2026-27 do daty."""
    D = DANE_NBA[co]
    w0, w1 = 1.0 / D["s0"] ** 2, n26 / D["sd_gry"] ** 2
    post = (w0 * D["m0"] + w1 * (liga26 if n26 else 0.0)) / (w0 + w1)
    return post, (w0 + w1) ** -0.5


def _nba_z_druzyn(co, pred, liga26, n26):
    D = DANE_NBA[co]
    env, env_sd = _nba_srodowisko(co, liga26, n26)
    return env + D["b1"] * (pred - D["liga25"]), math.sqrt(D["sd"] ** 2 + env_sd ** 2)


def nba_ftm_mecz(pred, liga26, n26, kraw, srednia=None, info=False):
    """Rzuty wolne TRAFIONE w meczu (obie druzyny razem), BRAK RYNKU. Model druzynowy + reszta NB.
    pred  = ((FT_A + FT_przeciwnikow_B)/2) + ((FT_B + FT_przeciwnikow_A)/2) z sezonu 2025-26: FT_X = rzuty wolne trafione na mecz przez
            druzyne X, FT_przeciwnikow_X = trafione przez rywali X (Opponent Per Game). Basketball-reference.com, strona sezonu
            (2025-26 = NBA_2026.html, tabele "Team Per Game Stats" i "Opponent Per Game Stats", kolumna FT).
    liga26 = srednia SUMY FTM obu druzyn w meczu w sezonie 2026-27 do dzis (= 2 x srednia druzyny z wiersza League Average, FT);
    n26    = liczba rozegranych meczow ligi 2026-27 (suma kolumny G wszystkich druzyn / 2). Przed pierwszym meczem: n26=0.
    Srednia = poziom ligi na poczatku sezonu (prior 38,8 +- 3,1: w 1. dwoch tygodniach FTM jest WYZSZE niz w sezonie, aktualizowany
    n26 meczami) + 1,021 * (pred - 36,76); sd reszty 9,30 (miedzysezonowo, n=222) oraz niepewnosc poziomu ligi. Kalibracja dotyczy
    POCZATKU sezonu (pierwsze ~30 dni); pozniej niezmierzona. srednia= reczne nadpisanie sredniej."""
    mu, sd = _nba_z_druzyn("ftm", pred, liga26, n26)
    if srednia is not None:
        mu = float(srednia)
    vm = sd ** 2 / mu
    p = _nba_biny(_nba_pmf(mu, vm, 90), kraw)
    return (p, {"srednia": mu, "sd": sd, "vm": vm}) if info else p


def nba_trojki_gracza(linie):
    """Srednia 3PM gracza z jego linii (NB, vm 1,20) BEZ mnoznika - skladnik sumy do nba_trojki_meczu. linie jak w nba_gracz."""
    return _nba_srednia(_nba_linie(linie), DANE_NBA["fg3_propsy"]["vm"], 20)


def nba_trojki_meczu(kraw, suma=None, n_graczy=0, pred=None, liga26=None, n26=0, info=False):
    """Trojki TRAFIONE w meczu (obie druzyny). Dwie drogi:
    (1) rynek graczy: suma = SUMA nba_trojki_gracza(linie_gracza) po WSZYSTKICH graczach obu druzyn, ktorzy maja linie trojek w dniu meczu
        (zwykle 9-16 graczy; musi byc >= 8, inaczej droga 2). Srednia = 13,74 + 0,569 * suma, sd 5,56 (kalibracja n=345 meczow:
        suma graczy slabo przewiduje mecz, zalezy od liczby graczy z linia - dlatego wspolczynnik < 1).
    (2) bez rynku (zapas): pred = suma po stronach ((3PM_A + 3PM przeciwnikow B)/2 + (3PM_B + 3PM przeciwnikow A)/2) z sezonu 2025-26
        (basketball-reference NBA_2026.html, kolumna 3P w Team i Opponent Per Game), liga26 i n26 jak w nba_ftm_mecz (kolumna 3P);
        srednia = poziom ligi (prior 26,4 +- 1,0) + 1,698 * (pred - 26,60), sd 4,85 + niepewnosc poziomu."""
    if suma is not None and n_graczy >= 8:
        G = DANE_NBA["fg3_propsy"]
        mu, sd = G["b0"] + G["b1"] * suma, G["sd"]
    else:
        assert pred is not None and liga26 is not None, "za malo graczy z linia (<8): podaj pred, liga26, n26"
        mu, sd = _nba_z_druzyn("fg3", pred, liga26, n26)
    vm = max(sd ** 2 / mu, 1.0001)
    p = _nba_biny(_nba_pmf(mu, vm, 80), kraw)
    return (p, {"srednia": mu, "sd": sd, "vm": vm}) if info else p


def nba_lift(p1, p2, rho=None):
    """Lift bin x bin z kopuli normalnej o korelacji rho dla dwoch pytan z JEDNEGO meczu (biny w kolejnosci liczbowej); marginalia
    zachowane z konstrukcji. Domyslne rho = total x asysty gracza (0,186, t 6,7 - JEDYNA para, ktora wchodzi). Pozostale
    (punkty gracza x FTM meczu 0,064 t 2,2; PRA x trojki meczu 0,105 t 2,1; zbiorki x total 0,03) ponizej progu t 2,6 = iloczyn;
    kwarta x zbiorki niezalezne. Wynik: macierz len(p1) x len(p2); wspolny rozklad = lift * outer(p1, p2), potem IPF do marginaliow."""
    rho = DANE_NBA["rho"]["total_asysty"]["rho"] if rho is None else rho
    p1, p2 = np.asarray(p1, dtype=float), np.asarray(p2, dtype=float)
    z = lambda p: np.array([-8.0] + [float(np.clip(_nba_ppf(c), -8, 8)) for c in np.clip(np.cumsum(p)[:-1], 1e-12, 1 - 1e-12)] + [8.0])
    z1, z2 = z(p1), z(p2)
    s = math.sqrt(1 - rho * rho)
    x, w = np.polynomial.legendre.leggauss(240)

    def F(a, b):   # P(X<=a, Y<=b) = int_{-8}^{a} phi(t) Phi((b - rho t)/s) dt
        t = (a + (-8.0)) / 2 + (a - (-8.0)) / 2 * x
        return float(((a + 8.0) / 2 * w * np.exp(-t * t / 2) / math.sqrt(2 * math.pi) * _nba_norm_cdf((b - rho * t) / s)).sum())
    Fm = np.array([[F(a, b) if a > -8 and b > -8 else 0.0 for b in z2] for a in z1])
    J = np.clip(Fm[1:, 1:] - Fm[:-1, 1:] - Fm[1:, :-1] + Fm[:-1, :-1], 0, None)
    return J / np.maximum(np.outer(p1, p2), 1e-300)


def _nba_ppf(p):
    """Odwrotna dystrybuanta normalna (bisekcja, bez scipy)."""
    lo, hi = -9.0, 9.0
    for _ in range(80):
        m = (lo + hi) / 2
        lo, hi = (m, hi) if float(_nba_norm_cdf(m)) < p else (lo, m)
    return (lo + hi) / 2
